"""Word receipts are generated by Flask after COMMIT, not by a database trigger."""
import io
import os
import tempfile
from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from db import query


def receipt_bytes(sale_id):
    sale = query('SELECT s.*,e.name AS employee FROM sales s JOIN employees e ON e.id=s.employee_id WHERE s.id=%s',(sale_id,),one=True)
    if not sale: raise ValueError('Sale not found.')
    items = query('SELECT i.*,p.name,i.quantity*i.unit_price AS total FROM sale_items i JOIN products p ON p.id=i.product_id WHERE sale_id=%s ORDER BY i.id',(sale_id,))
    document = Document()
    section = document.sections[0]
    section.top_margin = section.bottom_margin = Inches(0.7)
    for style in ('Normal','Title','Heading 1'):
        document.styles[style].font.name = 'Calibri'
        document.styles[style].font.color.rgb = RGBColor(0,0,0)
    document.styles['Normal'].font.size = Pt(11)
    document.add_heading('Hardware World Sales Receipt',0)
    document.add_paragraph(f'Receipt {sale_id:06d}\nDate {sale["created_at"]}\nCustomer {sale["customer_name"]}\nServed by {sale["employee"]}')
    currency = os.getenv('CURRENCY','UGX')
    table = document.add_table(rows=1, cols=4)
    table.style = 'Light Shading Accent 1'
    for cell,text in zip(table.rows[0].cells,('Product','Quantity','Unit price','Amount')): cell.text=text
    for item in items:
        for cell,text in zip(table.add_row().cells,(item['name'],str(item['quantity']),f'{item["unit_price"]:,.2f}',f'{item["total"]:,.2f}')): cell.text=text
    document.add_paragraph(f'Total paid {currency} {sum(i["total"] for i in items):,.2f}')
    document.add_paragraph('Payment recorded in full. Thank you for shopping with Hardware World.')
    output = io.BytesIO()
    document.save(output)
    output.seek(0)
    return output


def save_receipt(sale_id, directory):
    directory = Path(directory)
    directory.mkdir(parents=True,exist_ok=True)
    target = directory / f'sale-{sale_id}.docx'
    with tempfile.NamedTemporaryFile(dir=directory, suffix='.docx',delete=False) as handle:
        temporary = Path(handle.name)
        handle.write(receipt_bytes(sale_id).getvalue())
    try: temporary.replace(target)
    finally: temporary.unlink(missing_ok=True)
    return target
